+      await h.agent.run();
+      expect(
+        h.postLog.existsSync(),
+        isFalse,
+        reason: 'the Java skipFieldUpdate condition is strict mode + no '
+            'output response, regardless of the exit code',
+      );
+    } finally {
+      await h.dispose();
+    }
+  });
+}
