/// Executes a CliAgent job — Dart port of Java `CliAgent`.
///
/// Lifecycle (exact order, mirrors Java `CliAgent.runJobImpl`):
/// ```text
/// setup → preJSAction → preCliJSAction → cliCommands → postJSAction →
/// cache → reset (always runs, even on failure)
/// ```
///
/// Script hooks (`setup`/`cache`/`reset`) run as shell commands unless the
/// path ends with `.js` — then they execute via [JsJobRunner]. JS actions
/// (`preJSAction`/`preCliJSAction`/`postJSAction`) always run via
/// [JsJobRunner]. During the `cliCommands` phase, three further JS actions may
/// fire when configured: `timerJSAction` (periodic, plus a final tick),
/// `cliExecutionErrorJSAction` (on a non-zero exit), and `cliOutputLineJSAction`
/// (per output line; returning `true` stops the batch). Errors in hooks and
/// actions are caught and logged (the lifecycle continues); only CLI command
/// failures can fail the run.
///
/// Strict mode (`requireCliOutputFile=true`) with no CLI output file skips
/// `postJSAction` entirely (Java `skipFieldUpdate` parity, epam/dm.ai#622) —
/// the error summary returned as the response reports the failure instead.
library;

import 'dart:convert';
import 'dart:io';

import '../config/env_file_parser.dart';
import '../config/property_reader.dart';
import '../config/property_reader_getters.dart';
import '../js/job_runner.dart';
import 'cli_agent_params.dart';
import 'cli_command_builder.dart';
import 'cli_execution_helper.dart';
import 'ticket_input_context_builder.dart';

/// Executes a CliAgent job — lightweight CLI-agent orchestrator.
///
/// Takes the CLI-execution parts of `Teammate` and removes the
/// tracker-ticket plumbing: runs cursor-agent / claude / copilot-style CLI
/// tools with aggregated prompts and optional setup/cache/reset hooks,
/// without needing an `inputJql` or a ticket system.
class CliAgent {
  /// Creates a CliAgent with the given [params].
  ///
  /// - [workingDirectory] — overrides `params.workingDirectory` when set.
  /// - [ticketData] — raw tracker ticket JSON for the input context; in a
  ///   real run this is fetched from Jira/ADO via the tracker client.
  /// - [propertyReader] — property resolution; defaults to a new reader.
  /// - [jsRunner] — JS execution engine; defaults to [JsJobRunner].
  CliAgent({
    required this.params,
    this.workingDirectory,
    this.ticketData,
    PropertyReader? propertyReader,
    JsJobRunner? jsRunner,
  })  : propertyReader = propertyReader ?? PropertyReader(),
        jsRunner = jsRunner ?? const JsJobRunner();

  /// Parameters from the job config.
  final CliAgentParams params;

  /// Working-directory override; when null, `params.workingDirectory` or
  /// the CWD is used.
  final String? workingDirectory;

  /// Raw tracker ticket JSON used to populate the input context.
  ///
  /// When null (no tracker configured), the input context folder is created
  /// empty — the ticket-agnostic behavior.
  final Map<String, dynamic>? ticketData;

  /// Property reader for environment resolution.
  final PropertyReader propertyReader;

  /// JS runner for `.js` actions and hooks.
  final JsJobRunner jsRunner;

  /// Result of the `cliCommands` phase — used by the reset hook.
  CliExecutionResult? _cliResult;

  /// Input context path — cleaned up in the finally block.
  String? _inputContextPath;

  /// Ticket data as seen by the JS actions (`params.ticket`).
  ///
  /// Either the tracker-fetched [ticketData] (Teammate job) or, when absent,
  /// `input/<contextId>/ticket.json` loaded by convention (direct
  /// `dmtools run` launches, e.g. the machine's review/rework runners).
  /// Set once at the start of the lifecycle.
  Map<String, dynamic>? _resolvedTicketData;

  /// Runs the full lifecycle. Returns a result map.
  ///
  /// - Success: `{'success': true, 'contextId': …, 'response': …}`
  /// - Failure: `{'success': false, 'error': …}`
  ///
  /// The reset hook and folder cleanup always run (in a `finally` block),
  /// mirroring the Java `runJobImpl` finally semantics.
  Future<Map<String, dynamic>> run() async {
    if (params.cliCommands.isEmpty) {
      return {'success': true, 'message': 'No cliCommands provided'};
    }
    // Zone-scoped overrides: two CliAgent jobs running concurrently in one
    // isolate each keep their own `TrackerParams.envVariables` across
    // awaits (Java gets this from ThreadLocal).
    return PropertyReader.runWithOverrides(
      params.envVariables ?? {},
      _runGuarded,
    );
  }

  /// Runs the lifecycle, converting failures into error results.
  Future<Map<String, dynamic>> _runGuarded() async {
    try {
      return await _runLifecycle(_resolveWorkingDirectory());
    } catch (e) {
      return {'success': false, 'error': e.toString()};
    }
  }

  /// Executes the main lifecycle phases inside [workDir].
  Future<Map<String, dynamic>> _runLifecycle(String workDir) async {
    String? response;
    try {
      _resolvedTicketData = _resolveTicketData(workDir);
      _clearStaleOutputs(workDir);
      await _executeScriptHook('setup', params.setup, workDir, null);
      _executeJsAction('preJSAction', params.preJSAction, null, null, workDir);
      _inputContextPath = _createInputContext(workDir);
      _executeJsAction(
        'preCliJSAction',
        params.preCliJSAction,
        null,
        _inputContextPath,
        workDir,
      );
      response = await _executeCliCommands(workDir);
      if (_strictModeMissingOutput) {
        // Java `skipFieldUpdate` parity (epam/dm.ai#622, #409): in strict
        // mode, never run postJSAction against the failed/missing CLI
        // response — a post action like closeQuestionTicket would move
        // tickets to Done on a genuine CLI failure. The error summary in
        // `response` reports the failure instead.
        stderr.writeln(
          'Skipping postJSAction due to missing CLI output file '
          '(requireCliOutputFile=true)',
        );
      } else {
        _executeJsAction(
          'postJSAction',
          params.postJSAction,
          response,
          _inputContextPath,
          workDir,
        );
      }
      await _executeScriptHook('cache', params.cache, workDir, response);
      return {
        'success': true,
        'contextId': params.contextId,
        'response': response,
      };
    } finally {
      await _executeScriptHook(
        'reset',
        params.reset,
        workDir,
        _cliResult != null ? _extractResponse(_cliResult!) : null,
      );
      _performCleanup(workDir);
    }
  }

  // ------------------------------------------------------------------
  // Script hooks (setup / cache / reset)
  // ------------------------------------------------------------------

  /// Executes a script hook: `.js` path via [JsJobRunner], else shell.
  ///
  /// Errors are caught and logged — the lifecycle continues (mirrors Java
  /// `executeScriptHook`).
  Future<void> _executeScriptHook(
    String name,
    String? script,
    String workDir,
    String? response,
  ) async {
    if (script == null || script.trim().isEmpty) return;
    try {
      if (script.endsWith('.js')) {
        jsRunner.runScript(
          scriptPath: script,
          jobParams: _buildJobParams(response, null),
          workingDirectory: workDir,
          config: JsRunConfig(
            extraGlobals: {'workingDirectory': workDir},
          ),
        );
      } else {
        await _runShell(script, workDir, applyEnvFilters: false);
      }
    } catch (e) {
      stderr.writeln('$name hook failed, continuing: $e');
    }
  }

  /// Runs [command] as a shell command in [workDir].
  Future<void> _runShell(
    String command,
    String workDir, {
    required bool applyEnvFilters,
  }) async {
    final env = _buildSubprocessEnvironment(workDir, applyEnvFilters);
    await Process.run(
      '/bin/sh',
      ['-c', command.trim()],
      workingDirectory: workDir,
      environment: env,
    );
  }

  // ------------------------------------------------------------------
  // JS actions (preJSAction / preCliJSAction / postJSAction)
  // ------------------------------------------------------------------

  /// Execute…

content.text:
/// Teammate job — Dart port of Java `Teammate` (`teammate/Teammate.java`),
/// ticket-driven mode only: the job selects tickets by `inputJql`, prepares
/// the `input/<ticketKey>/` context folder, and delegates each ticket to
/// [CliAgent] under the hood.
///
/// Scope note (port decision): Java Teammate's internal AI-processing branch
/// (`ContextOrchestrator` + `RequestDecompositionAgent` + LLM providers) is
/// intentionally not ported — the dmtools-agents Teammate configs run with
/// `skipAIProcessing: true` and let the CLI agent do the AI work via
/// `cliCommands`. Everything the configs actually use is ported:
/// ticket selection, the CI-run trace comment, and the full CliAgent
/// lifecycle (preJSAction → input folder → preCliJSAction → cliCommands →
/// postJSAction → reset).
library;

import '../config/property_reader.dart';
import '../js/job_runner.dart';
import '../js/sync_tool_dispatcher.dart';
import 'dart:convert';
import 'dart:io';

import 'cli_agent.dart';
import 'github_ticket_source.dart';
import 'github_tracker_client.dart';
import 'cli_agent_params.dart';

/// Fetches the hydrated tickets for [inputJql]: each ticket is a raw tracker
/// JSON map with at least `key` and `fields` (comments included).
typedef TeammateTicketSource = Future<List<Map<String, dynamic>>> Function(
    String inputJql);

/// Posts a trace/status comment to [key] (Jira comment parity).
typedef TeammateCommentPoster = Future<void> Function(String key, String body);

/// Ticket-driven Teammate job.
///
/// Runs one [CliAgent] per ticket resolved from `params.inputJql`:
/// - empty/missing `inputJql` → no-op success (Java: "skipping ticket
///   processing");
/// - each ticket becomes the [CliAgentParams] context id, so the input
///   folder is `input/<ticketKey>/`;
/// - `ciRunUrl` + enabled comments post the Java trace comment
///   (`[<agentId>] Processing started. CI Run: <url>`).
class TeammateJob {
  /// Creates the job from the raw `params` block of a Teammate config.
  ///
  /// - [ticketSource] — ticket lookup; defaults to the Jira sync tools
  ///   (search → get_ticket → get_comments hydration).
  /// - [commentPoster] — comment sink for the CI-run trace comment; defaults
  ///   to `jira_post_comment`.
  TeammateJob({
    required this.params,
    this.workingDirectory,
    this.ticketSource,
    this.commentPoster,
    this.propertyReader,
    this.jsRunner,
  });

  /// Raw params from the job config (the `params` block).
  final Map<String, dynamic> params;

  /// Working-directory override forwarded to each [CliAgent].
  final String? workingDirectory;

  /// Ticket lookup override (tests inject fakes; default: Jira sync tools).
  final TeammateTicketSource? ticketSource;

  /// Comment sink override (tests inject fakes; default: `jira_post_comment`).
  final TeammateCommentPoster? commentPoster;

  /// Property reader forwarded to each [CliAgent].
  final PropertyReader? propertyReader;

  /// JS runner forwarded to each [CliAgent].
  final JsJobRunner? jsRunner;

  /// Runs the job and returns `{'success': …, 'results': […]}` where each
  /// result item carries `ticket`, plus the [CliAgent] result fields.
  Future<Map<String, dynamic>> run() async {
    final inputJql = (params['inputJql'] as String?)?.trim() ?? '';
    if (inputJql.isEmpty) {
      // Issues-driven pass-through: the caller prepared `input/ticket.md`
      // (e.g. the ai-teammate workflow wrote the issue body). Run
      // the config AS-IS through one [CliAgent] with a synthetic ticket —
      // the canonical `input/<contextId>/` context is built from it.
      // Without a prepared input this is Java parity: "skipping ticket
      // processing" → empty result list.
      final prepared = _preparedInputTicket();
      if (prepared == null) {
        return const {'success': true, 'results': []};
      }
      _consumePreparedInput();
      return _runSingle(prepared);
    }
    final github = looksLikeGithubQuery(inputJql);
    _sourceIsGithub = github;
    final source =
        ticketSource ?? (github ? githubIssueTicketSource : jiraTicketSource);
    final tickets = await source(inputJql);
    final results = <Map<String, dynamic>>[];
    for (final ticket in tickets) {
      final key = _ticketKey(ticket);
      if (key == null || key.isEmpty) {
        results.add({
          'ticket': null,
          'success': false,
          'error': 'search result without a ticket key',
        });
        continue;
      }
      await _postTraceComment(key);
      final agent = CliAgent(
        params: _paramsForTicket(key),
        workingDirectory: workingDirectory,
        ticketData: ticket,
        propertyReader: propertyReader,
        jsRunner: jsRunner,
      );
      final result = await agent.run();
      results.add(
          {'ticket': key, 'success': result['success'] == true, ...result});
    }
    final ok = results.isNotEmpty && results.every((r) => r['success'] == true);
    return {'success': ok, 'results': results};
  }

  /// Runs one [CliAgent] against a single prepared [ticket] (no per-ticket
  /// contextId override and no Jira trace comment — there is no tracker).
  Future<Map<String, dynamic>> _runSingle(Map<String, dynamic> ticket) async {
    final agent = CliAgent(
      params: CliAgentParams.fromJson(params),
      workingDirectory: workingDirectory,
      ticketData: ticket,
      propertyReader: propertyReader,
      jsRunner: jsRunner,
    );
    final result = await agent.run();
    final key = _ticketKey(ticket);
    return {
      'success': result['success'] == true,
      'results': [
        {'ticket': key, 'success': result['success'] == true, ...result}
      ],
    };
  }

  /// The caller-provided ticket at `<workDir>/input/ticket.md`, mapped to
  /// the raw-tracker shape [CliAgent] understands (first line → summary,
  /// the rest → description), or null when absent/blank.
  Map<String, dynamic>? _preparedInputTicket() {
    final base = workingDirectory ?? Directory.current.path;
    final file = File('$base/input/ticket.md');
    if (!file.existsSync()) return null;
    final content = file.readAsStringSync().trim();
    if (content.isEmpty) return null;
    final newline = content.indexOf('\n');
    final summary =
        newline < 0 ? content : content.substring(0, newline).trim();
    final description =
        newline < 0 ? '' : content.substring(newline + 1).trim();
    return {
      'key': _contextId(),
      'fields': {'summary': summary, 'description': description},
    };
  }

  /// Deletes the consumed bootstrap `input/ticket.md`.
  ///
  /// The ticket now lives in memory and the canonical `input/<contextId>/`
  /// context is built from it by [CliAgent]; the root copy must not
  /// survive the consumption — left in the tree it (a) duplicates the
  /// ticket body next to the canonical context and (b) leaks an
  /// uncommitted runtime file into the agent's git flow: the branch-setup
  /// stash pops it onto the tracked version with conflict markers that
  /// the agent's final `git add -A` then commits (seen on fa gh-671:
  /// `input/ticket.md` and `input/gh-671/ticket.md` both carried
  /// `<<<<<<< Updated upstream` blocks). Best-effort — a locked file
  /// must not fail the job.
  void _consumePreparedInput() {
    final base = workingDirectory ?? Directory.current.path;
    final file = File('$base/input/ticket.md');
    if (!file.existsSync()) return;
    try {
      file.deleteSync();
    } catch (_) {
      // Best-effort: never fail the job over cleanup.
    }
  }

  /// The config's `metadata.contextId`, falling back to CliAgent's own
  /// `'cli-agent'` default.
  String _contextId() {
    final md = params['metadata'];
    if (md is Map) {
      final contextId = md['contextId'];
      if (contextId is String && contextId.isNotEmpty) return contextId;
    }
    return 'cli-agent';
  }

  /// Per-ticket [CliAgentParams]: the shared config with `metadata.contextId`
  /// pinned to the ticket key (Java Teammate's input folder is
  /// `input/<ticketKey>/`).
  CliAgentParams _paramsForTicket(String key) {
    final p = CliAgentParams.fromJson(params);
    p.metadata = {...?p.metadata, 'contextId': key};
    return p;
  }

  /// Posts the CI-run trace comment when `ciRunUrl` is set and comments are
  /// enabled (`alwaysPostComments` or non-`none` `outputType`).
  ///
  /// The default sink follows the ticket source: GitHub-sourced tickets
  /// post through [GithubTrackerClient] (Java `trackerClient.postComment`
  /// with `DEFAULT_TRACKER=github`), everything else through
  /// `jira_post_comment`. A failed trace comment never fails the job —
  /// Java catches, warns, and continues.
  Future<void> _postTraceComment(String key) async {
    final ciRunUrl = (params['ciRunUrl'] as String?)?.trim() ?? '';
    if (ciRunUrl.isEmpty || !_shouldPostComments) return;
    final poster = commentPoster ??
        (_sourceIsGithub ? _githubCommentPoster : _jiraCommentPoster);
    try {
      await poster(
          key,
          '${_agentNamePrefix()}'
          'Processing started. CI Run: $ciRunUrl');
    } catch (_) {
      // Advisory comment only — processing continues (Java parity).
    }
  }

  /// Java `AbstractJob.shouldPostComments`: `alwaysPostComments` wins, else
  /// comments are on when `outputType` is not `none`.
  bool get _shouldPostComments {
    if (params['alwaysPostComments'] == true) return true;
    final outputType = (params['outputType'] as String?)?.trim().toLowerCase();
    return outputType != null && outputType.isNotEmpty && outputType != 'none';
  }

  /// Whether the resolved ticket source is the GitHub-issues one — trace
  /// comments are Jira-specific and are skipped in that mode.
  bool _sourceIsGithub = false;

  /// Java `AbstractJob.agentNamePrefix`: `[<contextId>|<agentId>] ` or `''`.
  String _agentNamePrefix() {
    final md = params['metadata'];
    if (md is Map) {
      final contextId = md['contextId'];
      if (contextId is String && contextId.isNotEmpty) return '[$contextId] ';
      final agentId = md['agentId'];
      if (agentId is String && agentId.isNotEmpty) return '[$agentId] ';
    }
    return '';
  }

  /// Extracts the ticket key from a raw search/get result map.
  String? _ticketKey(Map<String, dynamic> ticket) {
    final key = ticket['key'];
    return key is String ? key : null;
  }
}

/// Default [TeammateTicketSource]: Jira sync tools — `jira_search_by_jql`
/// for the keys, then `jira_get_ticket` + `jira_get_comments` hydration so
/// the input folder carries the full ticket text and comments
/// (Java `TicketContext.prepareContext` parity).
Future<List<Map<String, dynamic>>> jiraTicketSource(String inputJql) async {
  final dispatcher = SyncToolDispatcher(PropertyReader());
  final raw = dispatcher.execute('jira_search_by_jql', {
    'jql': inputJql,
    'fields': ['summary', 'status', 'priority', 'labels'],
  });
  final keys = extractTicketKeys(raw);
  return [
    for (final key in keys)
      hydrateTicket(
        rawTicket: dispatcher.execute('jira_get_ticket', {'key': key}),
        rawComments: dispatcher.execute('jira_get_comments', {'key': key}),
        key: key,
      ),
  ];
}

Future<void> _jiraCommentPoster(String key, String body) async {
  final dispatcher = SyncToolDispatcher(PropertyReader());
  dispatcher.execute('jira_post_comment', {'key': key, 'comment': body});
}

/// Default comment sink for GitHub-sourced tickets: the write-side
/// GitHub issues tracker client (Java `GitHubTrackerClient.postComment`).
Future<void> _githubCommentPoster(String key, String body) async {
  GithubTrackerClient().postComment(key, body);
}

/// Merges a raw ticket payload and a raw comments payload into one ticket
/// map whose `fields.comments` carries the comments (the shape
/// `TicketInputContextBuilder` consumes). Falls back to `{'key': key}`
/// when [rawTicket] does not decode.
Map<String, dynamic> hydrateTicket({
  String? rawTicket,
  String? rawComments,
  required String key,
}) {
  final ticket = _decodeMap(rawTicket) ?? {'key': key};
  final comments = decodeCommentsPayload(rawComments);
  if (comments == null && ticket['fields'] is! Map) return ticket;
  final fields = Map<String, dynamic>.from(
    ticket['fields'] as Map<String, dynamic>? ?? const {},
  );
  if (comments != null) fields['comment'] = {'comments': comments};
  ticket['fields'] = fields;
  return ticket;
}

/// Decodes a search-result payload into ticket keys. Accepts both a bare
/// issues array (`[{key, …}, …]`) and the paged map (`{issues: […]}`) —
/// the two shapes Jira search returns across API versions.
List<String> extractTicketKeys(String? raw) {
  final decoded = decodeJsonPayload(raw);
  if (decoded is List) {
    return decoded.map(_mapKey).whereType<String>().toList();
  }
  if (decoded is Map) {
    final issues = decoded['issues'];
    if (issues is List) return issues.map(_mapKey).whereType<String>().toList();
  }
  return const [];
}

/// Returns the `key` of [value] when it is a map with a string key.
String? _mapKey(dynamic value) {
  if (value is Map<String, dynamic>) return value['key'] as String?;
  if (value is Map) return value['key'] as String?;
  return null;
}

/// Decodes a comments payload: either `{comments: […]}` (the raw Jira
/// issue-comment response) or a bare array.
List<dynamic>? decodeCommentsPayload(String? raw) {
  final decoded = decodeJsonPayload(raw);
  if (decoded is Map && decoded['comments'] is List) {
    return decoded['comments'] as List;
  }
  if (decoded is List) return decoded;
  return null;
}

/// Decodes a JSON payload string, returning `null` for empty or malformed
/// input (network bodies are best-effort — Java treats undecodable bodies
/// the same way by failing the search, which the dispatcher surfaces).
dynamic decodeJsonPayload(String? raw) {
  if (raw == null || raw.isEmpty) return null;
  try {
    return jsonDecode(raw);
  } on FormatException {
    return null;
  }
}

Map<String, dynamic>? _decodeMap(String? raw) {
  final decoded = decodeJsonPayload(raw);
  if (decoded is Map<String, dynamic>) return decoded;
  if (decoded is Map) return decoded.cast<String, dynamic>();
  return null;
}

/// Parameters for [CliAgent] — Dart port of Java `CliAgentParams`.
///
/// Extends the `TrackerParams` contract (outputType, envVariables, metadata,
/// preJSAction, postJSAction, ...) but does not require `inputJql`. The job
/// is designed to run CLI agents in a lightweight, ticket-agnostic mode.
///
/// Every key, type, and default matches the Java contract exactly — see
/// the parameter table in GOAL.md → Phase 5.
library;

/// Parameters for the [CliAgent] job.
///
/// Ported from Java `CliAgentParams` which extends `TrackerParams`.
/// The `cliPrompts` field accepts both a flat string array (backward
/// compatibility) and a structured config (array of strings and/or
/// `{"id":"…","prompts":[…]}` section objects).
///
/// Fields are mutable so that [fromJson] and test code can set them
/// without a 26-parameter constructor (quality-gate max-params = 6).
class CliAgentParams {
  /// Creates params with all defaults applied.
  ///
  /// Use [CliAgentParams.fromJson] for production, or set fields directly
  /// via cascade syntax in tests:
  /// ```dart
  /// CliAgentParams()..cliCommands = ['echo']..setup = 'make setup';
  /// ```
  CliAgentParams();

  /// Optional smart input context (plain ticket-key string or config object).
  dynamic input;

  /// CLI commands to execute — required for the job to do anything.
  List<String> cliCommands = const [];

  /// Single base CLI prompt (appended to every command via temp file).
  String? cliPrompt;

  /// Structured CLI prompts — array of strings and/or section objects.
  dynamic cliPrompts;

  /// Tracker-specific CLI prompts, keyed by tracker type name.
  Map<String, List<String>>? cliPromptsByTracker;

  /// Setup hook — shell command or `.js` path (runs first).
  String? setup;

  /// Cache hook — shell command or `.js` path (runs after postJSAction).
  String? cache;

  /// Reset hook — shell command or `.js` path (always runs, even on failure).
  String? reset;

  /// Pre-CLI JS action path (runs before cliCommands).
  String? preCliJSAction;

  /// Whether to clean up the input folder after execution. Default: `true`.
  bool cleanupInputFolder = true;

  /// Whether to require an output file for success. Default: `false`.
  bool requireCliOutputFile = false;

  /// Working directory for command execution. Default: CWD.
  String? workingDirectory;

  /// Exact env variable names to exclude from the subprocess.
  List<String>? excludedEnvVariables;

  /// Regex patterns; matching env variable names are excluded.
  List<String>? excludeEnvVariablesByRegex;

  /// Timer JS action path, fired periodically during CLI execution.
  String? timerJSAction;

  /// Timer interval in seconds. Default: `60`.
  int timerIntervalSeconds = 60;

  /// Whether to clean up the outputs folder after execution.
  bool cleanupOutputsFolder = false;

  /// JS action path fired when a CLI command fails.
  String? cliExecutionErrorJSAction;

  /// JS action path fired for each output line; returning true stops.
  String? cliOutputLineJSAction;

  // --- Inherited from TrackerParams ---

  /// Output type — `comment`, `field`, `creation`, or `none`.
  String? outputType;

  /// Per-job environment variable overrides.
  Map<String, String>? envVariables;

  /// Job metadata (contains `contextId`, etc.).
  Map<String, dynamic>? metadata;

  /// Job initiator.
  String? initiator;

  /// Pre-JS action path (runs after setup, before preCliJSAction).
  String? preJSAction;

  /// Post-JS action path (runs after cliCommands, before cache).
  String? postJSAction;

  /// Custom parameters exposed to JS actions as `customParams`.
  Map<String, dynamic>? customParams;

  /// Returns the context ID from metadata, or `"cli-agent"` fallback.
  ///
  /// Mirrors `CliAgent.getContextId()`.
  String get contextId {
    final md = metadata;
    if (md != null && md['contextId'] is String) {
      final id = md['contextId'] as String;
      if (id.isNotEmpty) return id;
    }
    return 'cli-agent';
  }

  /// Returns `cliPrompts` as a flat string array, or `null`.
  ///
  /// Handles both plain string arrays and structured config (objects with
  /// `id`/`prompts` fields), matching the Java `CliPromptsConfig.toStringArray()`.
  List<String>? get cliPromptsAsArray => _flattenCliPrompts(cliPrompts);

  /// Creates params from a JSON map (the `params` block of a job config).
  factory CliAgentParams.fromJson(Map<String, dynamic> json) {
    return CliAgentParams()
      ..input = json['input']
      ..cliCommands = _parseStringList(json['cliCommands'])
      ..cliPrompt = _parseString(json['cliPrompt'])
      ..cliPrompts = json['cliPrompts']
      ..cliPromptsByTracker =
          _parsePromptsByTracker(json['cliPromptsByTracker'])
      ..setup = _parseString(json['setup'])
      ..cache = _parseString(json['cache'])
      ..reset = _parseString(json['reset'])
      ..preCliJSAction = _parseString(json['preCliJSAction'])
      ..cleanupInputFolder = _parseBool(json['cleanupInputFolder'], true)
      ..requireCliOutputFile = _parseBool(json['requireCliOutputFile'], false)
      ..workingDirectory = _parseString(json['workingDirectory'])
      ..excludedEnvVariables = _parseStringList(json['excludedEnvVariables'])
      ..excludeEnvVariablesByRegex =
          _parseStringList(json['excludeEnvVariablesByRegex'])
      ..timerJSAction = _parseString(json['timerJSAction'])
      ..timerIntervalSeconds = _parseInt(json['timerIntervalSeconds'], 60)
      ..cleanupOutputsFolder = _parseBool(json['cleanupOutputsFolder'], false)
      ..cliExecutionErrorJSAction =
          _parseString(json['cliExecutionErrorJSAction'])
      ..cliOutputLineJSAction = _parseString(json['cliOutputLineJSAction'])
      ..outputType = _parseString(json['outputType'])
      ..envVariables = _parseStringMap(json['envVariables'])
      ..metadata = _parseDynamicMap(json['metadata'])
      ..initiator = _parseString(json['initiator'])
      ..preJSAction = _parseString(json['preJSAction'])
      ..postJSAction = _parseString(json['postJSAction'])
      ..customParams = _parseDynamicMap(json['customParams']);
  }
}

// ----------------------------------------------------------------------
// JSON parsing helpers (top-level, private to this library).
// ----------------------------------------------------------------------

String? _parseString(dynamic value) => value == null ? null : value.toString();

bool _parseBool(dynamic value, bool defaultValue) {
  if (value is bool) return value;
  if (value is String) return value.toLowerCase() == 'true';
  return defaultValue;
}

int _parseInt(dynamic value, int defaultValue) {
  if (value is int) return value;
  if (value is num) return value.toInt();
  return defaultValue;
}

List<String> _parseStringList(dynamic value) {
  if (value is List) {
    return value.whereType<String>().toList(growable: false);
  }
  return const [];
}

Map<String, String>? _parseStringMap(dynamic value) {
  if (value is Map) {
    return value.map((k, v) => MapEntry(k.toString(), v.toString()));
  }
  return null;
}

Map<String, dynamic>? _parseDynamicMap(dynamic value) {
  if (value is Map) {
    return value.map((k, v) => MapEntry(k.toString(), v));
  }
  return null;
}

Map<String, List<String>>? _parsePromptsByTracker(dynamic value) {
  if (value is! Map) return null;
  final result = <String, List<String>>{};
  for (final entry in value.entries) {
    if (entry.value is List) {
      result[entry.key.toString()] =
          (entry.value as List).whereType<String>().toList();
    }
  }
  return result;
}

/// Flattens `cliPrompts` (string array or structured config) to a flat list.
///
/// Each element can be a plain string or an object with `id` and `prompts`
/// keys (the `CliPromptsConfig` structured form). Returns `null` when the
/// input is null or empty.
List<String>? _flattenCliPrompts(dynamic value) {
  if (value == null || value is! List) return null;
  final result = <String>[];
  for (final item in value) {
    result.addAll(_flattenCliPromptItem(item));
  }
  return result.isEmpty ? null : result;
}

/// Flattens a single `cliPrompts` element (string or section object).
List<String> _flattenCliPromptItem(dynamic item) {
  if (item is String) return [item];
  if (item is! Map) return const [];
  final prompts = item['prompts'];
  if (prompts is! List) return const [];
  return prompts.whereType<String>().toList();
}

