+    params: CliAgentParams()
+      ..cliCommands = cliCommands
+      ..requireCliOutputFile = requireCliOutputFile
+      ..postJSAction = js.path
+      ..cleanupInputFolder = false,
+    workingDirectory: tmp.path,
+  );
+  return _Harness(agent, log, tmp);
+}

