  void _consumePreparedInput() {
    final base = workingDirectory ?? Directory.current.path;
    final file = File('$base/input/ticket.md');
    if (!file.existsSync()) return;
    try {
      file.deleteSync();
    } catch (_) {
      // Best-effort: never fail the job over cleanup.
    }
  }

