          tmp,
          'lines.js',
          'file_append({path: "$log", content: line + "\\n"});',
        );
        await (CliAgent(
          params: CliAgentParams()
            ..cliCommands = ["printf 'a\\nb\\nc\\n'"]
            ..cliOutputLineJSAction = js.path
            ..cleanupInputFolder = false,
          workingDirectory: tmp.path,
        )).run();
        expect(
